def chunks(n=4000, size=500):
    "`n` texts of `size` characters cut from `corpus(2000)` joined by spaces, repeated as needed."
    from laghu.core import corpus
    s = ' '.join(corpus(2000)); out = [s[i:i + size] for i in range(0, len(s), size)]
    return (out * -(-n // len(out)))[:n]

