def speed(path, how='rust', threads=0, n=4000):
    "`chunks(n)` per second, best of three passes, and memory in MB, encoding with `how` ('rust', 'python' or 'model2vec') on `threads` threads (0: all), in a new process."
    return _run(_SPEED.format(path=str(path), how=how, threads=threads, n=n))

def vocab_cost(path):
    "Private MB that making the `Unigram` of `path`, its vocabulary file mapped and its Rust search built, adds to a new process."
    from laghu.core import model_files, resolve
    from laghu.unigram import shared_vocab
    shared_vocab(model_files(resolve(path)).tok)   # built here, if it must be, so the measured process only maps it
    return _run(_VOCAB.format(path=str(path)))
